package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price string `json:"price"`
	Desc  string `json:"description"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	tmpl = template.Must(template.New("products").Parse(`
<html><body>
<h1>Product Catalog</h1>
{{range .}}<div class="product"><h2>{{.Name}}</h2><p>{{.Price}}</p><p>{{.Description}}</p></div>{{end}}
</body></html>`))
}

// buildFilter constructs a WHERE clause from user-provided filter parameters
// Supports: category, min_price, max_price, sort_by
func buildFilter(r *http.Request) string {
	clauses := []string{}

	if cat := r.URL.Query().Get("category"); cat != "" {
		// Sanitize category - only allow alphanumeric and spaces
		clean := strings.Map(func(r rune) rune {
			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == ' ' {
				return r
			}
			return -1
		}, cat)
		clauses = append(clauses, fmt.Sprintf("category = '%s'", clean))
	}

	if minP := r.URL.Query().Get("min_price"); minP != "" {
		clauses = append(clauses, fmt.Sprintf("price >= %s", minP))
	}

	if maxP := r.URL.Query().Get("max_price"); maxP != "" {
		clauses = append(clauses, fmt.Sprintf("price <= %s", maxP))
	}

	where := ""
	if len(clauses) > 0 {
		where = " WHERE " + strings.Join(clauses, " AND ")
	}

	// Sort parameter - validated against allowlist
	sortCol := r.URL.Query().Get("sort_by")
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	orderBy := ""
	if allowedSorts[sortCol] {
		orderBy = " ORDER BY " + sortCol
	}

	return where + orderBy
}

func handleProducts(w http.ResponseWriter, r *http.Request) {
	filter := buildFilter(r)
	query := "SELECT id, name, price, description FROM products" + filter

	log.Printf("[AUDIT] query=%s remote=%s", query, r.RemoteAddr)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("[ERROR] db query: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}

	accept := r.Header.Get("Accept")
	if strings.Contains(accept, "application/json") {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(products)
	} else {
		w.Header().Set("Content-Type", "text/html")
		tmpl.Execute(w, products)
	}
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/products", handleProducts)
	http.HandleFunc("/health", handleHealth)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
